import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectRecordTitle,
  expectToast,
  relatedListRecord,
  selectPicklist,
  showRelatedList,
  waitForSpinners,
} from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Create Contact with valid 10-digit phone and non-Web Lead Source saves successfully', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-007 Create Contact with valid 10-digit phone and non-Web Lead Source saves successfully',
    { tag: ['@functional', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-007',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const contactLastname = data.unique('contact-lastname');
      await data.create('account-contact', ['Account']);
      await test.step('1. Navigate to the Account record page and click New Contact', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC5): Contact creation modal or page opens with required fields visible
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.lastName).toBeVisible();
      });
      await test.step("2. Enter Last Name 'TestContact', set Lead Source to any non-Web value (e.g. 'Word of mouth'), enter Phone '5551234567' (10 digits), click Save", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC5): Contact record is saved and the Contact detail page opens showing Last Name 'TestContact' and Phone '5551234567'
        await newContactDialog.lastName.fill(contactLastname);
        await selectPicklist(page, newContactDialog.leadSource, 'Word of mouth');
        await newContactDialog.phone.fill('5551234567');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectToast(page, contactLastname); // 1. the success toast names the record
        await expect(relatedListRecord(accountRecordPage.contactsRelatedList, contactLastname)).toBeVisible(); // 2. in the related list with that name
        await data.adopt('createdContact', 'Contact', 'LastName', contactLastname); // code-owned cleanup: tagged by its run-unique name
        await relatedListRecord(accountRecordPage.contactsRelatedList, contactLastname).click(); // 3. opened from the related list
        await expectRecordTitle(page, contactLastname);
        {
          // 4. SOQL by the run tag: exactly this record, with the values entered
          const saved = await data.tagged('Contact', { LastName: contactLastname }, [
            'LastName',
            'LeadSource',
            'Phone',
            'Account.Name',
          ]);
          expect(saved).toHaveLength(1);
          expect(saved[0]).toMatchObject({
            LastName: contactLastname,
            LeadSource: 'Word of mouth',
            Phone: '5551234567',
            'Account.Name': data.value('Account', 'Name'),
          });
        }
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('createdContact'), 'Phone')).toBe('5551234567');
        await expect
          .poll(() => soqlValue(sf, 'Contact', data.id('createdContact'), 'LeadSource'))
          .toBe('Word of mouth');
      });
    },
  );
});
